using FinOS.Analytics.Application.DTOs;using FinOS.Analytics.Domain.Interfaces;using MediatR;
namespace FinOS.Analytics.Application.Queries;
public record GetFinancialYearReviewQuery(long UserId,int StartYear):IRequest<FinancialYearReviewDto>;
public class GetFinancialYearReviewHandler(IMonthlyAggregateRepository monthly,INetWorthRepository netWorth):IRequestHandler<GetFinancialYearReviewQuery,FinancialYearReviewDto>{
public async Task<FinancialYearReviewDto>Handle(GetFinancialYearReviewQuery q,CancellationToken ct){var start=q.StartYear*100+4;var end=(q.StartYear+1)*100+3;var m=(await monthly.GetByUserAsync(q.UserId,36,ct)).Where(x=>x.YearMonth>=start&&x.YearMonth<=end).OrderBy(x=>x.YearMonth).ToList();var n=(await netWorth.GetByUserAsync(q.UserId,36,ct)).Where(x=>x.SnapshotDate>=new DateTime(q.StartYear,4,1)&&x.SnapshotDate<new DateTime(q.StartYear+1,4,1)).OrderBy(x=>x.SnapshotDate).ToList();var income=m.Sum(x=>x.TotalIncome);var expense=m.Sum(x=>x.TotalExpense);var savings=income-expense;var open=n.FirstOrDefault()?.NetWorth??0;var close=n.LastOrDefault()?.NetWorth??open;var growth=close-open;var rate=income==0?0:Math.Round(savings/income*100,2);var top=m.OrderByDescending(x=>x.TopExpenseAmount).FirstOrDefault();var win=growth>0?"Net worth increased during the financial year.":rate>=20?"Savings remained a meaningful share of income.":"No clear financial win is measurable from available data.";var weakness=rate<10?"Savings rate was below 10%.":growth<0?"Net worth declined during the financial year.":"No critical weakness was detected from available aggregates.";return new($"{q.StartYear}-{(q.StartYear+1)%100:00}",income,expense,savings,rate,open,close,growth,open==0?0:Math.Round(growth/Math.Abs(open)*100,2),win,weakness,top?.TopExpenseCategory??"Not available",top?.TopExpenseAmount??0,m.Select(x=>new MonthlyReportPointDto(x.YearMonth,x.TotalIncome,x.TotalExpense,x.TotalSavings)).ToList());}}
